window.SOURCE_DATA = {"files":[{"path":"snake_ai/game.py","title":"The game: board, rules and the 11 inputs","group":"The library","order":1,"lines":["\"\"\"Snake, with no graphics.","","The game is a grid of cells. The snake is a list of cells, head first. Every","step the head moves one cell in the current direction. If the new head lands on","the food the snake grows by one, otherwise the tail moves too, so the length","stays the same. Hitting a wall or the body ends the game.","","The agent never sees the grid. It sees 11 numbers (see ``get_state``) and","answers with one of 3 relative moves: keep going straight, turn right, or turn","left. That keeps the problem small enough for a tiny network to learn.","\"\"\"","","from __future__ import annotations","","from collections import deque","","import numpy as np","","# Directions as (dx, dy). y grows downwards, like rows on a screen, so UP is","# (0, -1). The list is in clockwise order, which makes turning a matter of","# moving one place along the list.","RIGHT = (1, 0)","DOWN = (0, 1)","LEFT = (-1, 0)","UP = (0, -1)","CLOCKWISE = [RIGHT, DOWN, LEFT, UP]","","# The three actions. They are relative to where the snake is heading, which","# means \"turn right\" works the same whether the snake is going up or left.","STRAIGHT = 0","TURN_RIGHT = 1","TURN_LEFT = 2","ACTION_NAMES = [\"straight\", \"right\", \"left\"]","N_ACTIONS = 3","","# Rewards. Everything the agent learns comes from these three numbers.","REWARD_FOOD = 10.0","REWARD_CRASH = -10.0","REWARD_STEP = 0.0","","STATE_LABELS = [","    \"danger ahead\",","    \"danger right\",","    \"danger left\",","    \"going right\",","    \"going down\",","    \"going left\",","    \"going up\",","    \"food left\",","    \"food right\",","    \"food up\",","    \"food down\",","]","STATE_SIZE = len(STATE_LABELS)","","","def turn(direction: tuple[int, int], action: int) -> tuple[int, int]:","    \"\"\"Return the new absolute direction after a relative action.\"\"\"","    i = CLOCKWISE.index(direction)","    if action == STRAIGHT:","        return direction","    if action == TURN_RIGHT:","        return CLOCKWISE[(i + 1) % 4]","    if action == TURN_LEFT:","        return CLOCKWISE[(i - 1) % 4]","    raise ValueError(f\"unknown action {action!r}, expected 0, 1 or 2\")","","","class SnakeGame:","    \"\"\"One game of Snake on a ``width`` x ``height`` grid.","","    ``step`` follows the usual reinforcement-learning shape: it takes an action","    and returns ``(state, reward, done, info)``.","","    ``info[\"terminal\"]`` tells a crash apart from a time-out. A crash is a real","    end of the game, so the future is worth nothing. A time-out only stops a","    snake that circles forever without eating; the game itself could have gone","    on, so the learner should not treat that state as worthless.","    \"\"\"","","    def __init__(self, width: int = 20, height: int = 20, seed: int | None = None,","                 idle_limit: int = 100):","        if width < 5 or height < 5:","            raise ValueError(\"the board must be at least 5 x 5\")","        self.width = width","        self.height = height","        # A game is cut short after idle_limit * len(snake) steps without food.","        self.idle_limit = idle_limit","        self.rng = np.random.default_rng(seed)","        self.reset()","","    # ------------------------------------------------------------------ setup","","    def reset(self) -> np.ndarray:","        \"\"\"Start a new game: a snake of length 3 in the middle, heading right.\"\"\"","        cx, cy = self.width // 2, self.height // 2","        self.direction = RIGHT","        self.snake: deque[tuple[int, int]] = deque([(cx, cy), (cx - 1, cy), (cx - 2, cy)])","        self.body = set(self.snake)  # same cells as self.snake, for O(1) lookups","        self.score = 0","        self.steps = 0","        self.steps_since_food = 0","        self.done = False","        self.end_reason = \"\"  # \"wall\", \"body\", \"timeout\" or \"won\" once the game is over","        self.food: tuple[int, int] | None = None","        self._place_food()","        return self.get_state()","","    def _place_food(self) -> None:","        \"\"\"Put the food on a random free cell. No free cell means the board is full.\"\"\"","        free = [(x, y) for y in range(self.height) for x in range(self.width)","                if (x, y) not in self.body]","        self.food = free[self.rng.integers(len(free))] if free else None","","    # ------------------------------------------------------------------ rules","","    def is_wall(self, point: tuple[int, int]) -> bool:","        x, y = point","        return not (0 <= x < self.width and 0 <= y < self.height)","","    def is_danger(self, point: tuple[int, int]) -> bool:","        \"\"\"Would moving the head onto ``point`` next step end the game?","","        The tail is not dangerous: on the next step it moves out of the way.","        (The only time it stays is when the snake eats, and the food can never","        be on the tail.)","        \"\"\"","        if self.is_wall(point):","            return True","        return point in self.body and point != self.snake[-1]","","    def step(self, action: int):","        \"\"\"Move one cell. Returns ``(state, reward, done, info)``.\"\"\"","        if self.done:","            raise RuntimeError(\"the game is over, call reset() first\")","","        self.direction = turn(self.direction, action)","        hx, hy = self.snake[0]","        dx, dy = self.direction","        new_head = (hx + dx, hy + dy)","        self.steps += 1","        self.steps_since_food += 1","","        eats = new_head == self.food","","        # Move the tail first. If the head moves into the cell the tail just","        # left, that is legal, so the tail must be gone before we check.","        tail = None","        if not eats:","            tail = self.snake.pop()","            self.body.discard(tail)","","        if self.is_wall(new_head) or new_head in self.body:","            if tail is not None:  # put the tail back so the final frame looks right","                self.snake.append(tail)","                self.body.add(tail)","            self.done = True","            reason = \"wall\" if self.is_wall(new_head) else \"body\"","            self.end_reason = reason","            return self.get_state(), REWARD_CRASH, True, {\"terminal\": True, \"reason\": reason}","","        self.snake.appendleft(new_head)","        self.body.add(new_head)","","        if eats:","            self.score += 1","            self.steps_since_food = 0","            self._place_food()","            if self.food is None:  # the snake fills the whole board","                self.done = True","                self.end_reason = \"won\"","                return self.get_state(), REWARD_FOOD, True, {\"terminal\": True, \"reason\": \"won\"}","            return self.get_state(), REWARD_FOOD, False, {\"terminal\": False, \"reason\": \"food\"}","","        if self.steps_since_food > self.idle_limit * len(self.snake):","            self.done = True","            self.end_reason = \"timeout\"","            return self.get_state(), REWARD_STEP, True, {\"terminal\": False, \"reason\": \"timeout\"}","","        return self.get_state(), REWARD_STEP, False, {\"terminal\": False, \"reason\": \"\"}","","    # ------------------------------------------------------------------ state","","    def get_state(self) -> np.ndarray:","        \"\"\"The 11 numbers the network sees, each 0 or 1. Order: ``STATE_LABELS``.\"\"\"","        hx, hy = self.snake[0]","        d = self.direction","        right_of = turn(d, TURN_RIGHT)","        left_of = turn(d, TURN_LEFT)","","        ahead = (hx + d[0], hy + d[1])","        right = (hx + right_of[0], hy + right_of[1])","        left = (hx + left_of[0], hy + left_of[1])","","        if self.food is None:","            food = (False, False, False, False)","        else:","            fx, fy = self.food","            food = (fx < hx, fx > hx, fy < hy, fy > hy)","","        return np.array([","            self.is_danger(ahead),","            self.is_danger(right),","            self.is_danger(left),","            d == RIGHT,","            d == DOWN,","            d == LEFT,","            d == UP,","            *food,","        ], dtype=np.float64)","","    # ------------------------------------------------------------------ display","","    def render_text(self) -> str:","        \"\"\"The board as text: ``#`` wall, ``O`` head, ``o`` body, ``*`` food.\"\"\"","        rows = [\"#\" * (self.width + 2)]","        head = self.snake[0]","        for y in range(self.height):","            row = [\"#\"]","            for x in range(self.width):","                p = (x, y)","                if p == head:","                    row.append(\"O\")","                elif p in self.body:","                    row.append(\"o\")","                elif p == self.food:","                    row.append(\"*\")","                else:","                    row.append(\" \")","            row.append(\"#\")","            rows.append(\"\".join(row))","        rows.append(\"#\" * (self.width + 2))","        return \"\\n\".join(rows)"],"blocks":[{"start":1,"end":12,"note":"<p>The module docstring says the one thing to remember: the agent never sees the grid, only 11 numbers, and answers with one of 3 relative moves. Everything else in the file serves those two facts.</p>"},{"start":13,"end":18,"note":"<p><code>from __future__ import annotations</code> lets the type hints use the modern <code>tuple[int, int] | None</code> syntax on older Pythons, because hints are then stored as strings and never evaluated.</p>"},{"start":19,"end":27,"note":"<p>Directions are offsets added to the head. <b>y grows downwards</b>, so UP is <code>(0, -1)</code>. The list is in clockwise order, which turns \"turn right\" into \"move one place along the list\" (see <code>turn</code>).</p>"},{"start":28,"end":35,"note":"<p>Actions are <b>relative</b> to the heading. Reversing is impossible by construction, and \"danger right, so do not turn right\" means the same thing whichever way the snake faces.</p>"},{"start":36,"end":40,"note":"<p>The entire learning signal. No reward for moving towards the food: I wanted to see whether the agent could find that from +10 alone. It can.</p>"},{"start":41,"end":56,"note":"<p>The names of the 11 inputs, in the order <code>get_state</code> produces them. The guide, <code>play.py</code> and the analysis all read this list so the labels can never drift out of sync with the code.</p>"},{"start":57,"end":68,"note":"<p><code>turn</code> maps a relative action to a new absolute direction with modular arithmetic on the clockwise list: right is index + 1, left is index - 1, and <code>% 4</code> wraps around. An unknown action raises instead of silently doing something.</p>"},{"start":69,"end":80,"note":"<p>The class follows the standard reinforcement-learning shape: <code>reset()</code> returns the first state, <code>step(action)</code> returns <code>(state, reward, done, info)</code>.</p><p>The docstring explains <code>info[\"terminal\"]</code>, which separates a real end (a crash) from a time-out. That distinction matters in the Bellman target (chapter 8).</p>"},{"start":81,"end":93,"note":"<p>The game owns its random generator, seeded, so a seed reproduces every food position. <code>idle_limit</code> sets the time-out: <code>idle_limit * len(snake)</code> steps without eating.</p>"},{"start":94,"end":108,"note":"<p>A fresh game: length 3 in the middle, heading right. <code>self.body</code> is a set with the same cells as the deque, because \"is this cell part of the body?\" is asked several times per step and a set answers in constant time. <code>end_reason</code> is filled in at the exact line where a game ends.</p>"},{"start":109,"end":116,"note":"<p>Food goes on a uniformly random free cell. Listing all free cells costs up to 400 checks, which is nothing next to a training step, and it can never loop forever the way \"pick a random cell until it is free\" can on a nearly full board. No free cell means the snake fills the board: a win.</p>"},{"start":117,"end":120,"note":"<p>Off the board in any direction.</p>"},{"start":121,"end":131,"note":"<p>\"Would the head die here next step?\" A wall, or a body cell <b>except the tail</b>, because the tail moves away on the same tick. The food can never be on the tail, so the tail always moves.</p>"},{"start":132,"end":143,"note":"<p>One tick. First turn, then compute the new head. <code>steps_since_food</code> drives the time-out.</p>"},{"start":144,"end":152,"note":"<p>The order that matters: <b>pop the tail before the collision check</b>. Otherwise moving into the cell the tail is leaving would count as a crash, and the agent would learn to fear a perfectly safe move. Chapter 2's figure lets you switch this bug on.</p>"},{"start":153,"end":161,"note":"<p>A crash: reward -10, <code>terminal=True</code>. The tail is put back first so the final frame shows the whole snake.</p>"},{"start":162,"end":174,"note":"<p>The move is legal: add the new head. If it ate, the tail was never popped, so the snake is one cell longer. A full board ends the game as a win.</p>"},{"start":175,"end":183,"note":"<p>The time-out. Reward 0 and <code>terminal=False</code>: the game could have continued, so the learner should still value the future from here. Treating it as a crash would teach the agent that ordinary positions are deadly.</p>"},{"start":184,"end":213,"note":"<p>The 11 inputs: three danger checks on the cells ahead, right and left of the head; the heading as a one-hot of four; and four food comparisons. Note <code>fy &lt; hy</code> is \"food up\", because y grows downwards. With no food (a won game) the food inputs are all 0.</p>"},{"start":214,"end":233,"note":"<p>A plain-text board, used by a test and handy in a debugger.</p>"}]},{"path":"snake_ai/network.py","title":"The network: forward pass, loss, backprop and Adam","group":"The library","order":2,"lines":["\"\"\"A two-layer neural network in plain NumPy: 11 inputs, 64 hidden, 3 outputs.","","    h = max(0, x @ W1 + b1)      hidden layer, ReLU","    q = h @ W2 + b2              one output per action, no activation","","The outputs are Q-values: the network's guess of the total future reward for","each of the three moves. They can be any real number, which is why the last","layer has no activation.","","Nothing here knows about Snake. ``forward`` and ``backward`` are the whole","network, ``q_loss`` is the error we train on, and ``Adam`` turns gradients into","weight updates.","\"\"\"","","from __future__ import annotations","","import json","","import numpy as np","","PARAM_NAMES = (\"W1\", \"b1\", \"W2\", \"b2\")","","","class QNetwork:","    def __init__(self, n_inputs: int = 11, n_hidden: int = 64, n_outputs: int = 3,","                 seed: int | None = None):","        rng = np.random.default_rng(seed)","        # He initialisation for the ReLU layer: variance 2 / fan_in keeps the","        # size of the signal roughly the same as it passes through the layer.","        self.W1 = rng.normal(0.0, np.sqrt(2.0 / n_inputs), size=(n_inputs, n_hidden))","        self.b1 = np.zeros(n_hidden)","        # The output layer is linear, so variance 1 / fan_in (LeCun / Xavier style).","        self.W2 = rng.normal(0.0, np.sqrt(1.0 / n_hidden), size=(n_hidden, n_outputs))","        self.b2 = np.zeros(n_outputs)","","    # ---------------------------------------------------------------- shapes","","    @property","    def sizes(self) -> tuple[int, int, int]:","        return self.W1.shape[0], self.W1.shape[1], self.W2.shape[1]","","    @property","    def params(self) -> dict[str, np.ndarray]:","        \"\"\"The weight arrays themselves (not copies), keyed by name.\"\"\"","        return {\"W1\": self.W1, \"b1\": self.b1, \"W2\": self.W2, \"b2\": self.b2}","","    def n_params(self) -> int:","        return sum(p.size for p in self.params.values())","","    # ---------------------------------------------------------------- forward","","    def forward(self, x: np.ndarray):","        \"\"\"Run a batch of states through the network.","","        ``x`` has shape (batch, 11). Returns the Q-values, shape (batch, 3), and","        a cache of the values ``backward`` needs.","        \"\"\"","        z1 = x @ self.W1 + self.b1","        h = np.maximum(0.0, z1)","        q = h @ self.W2 + self.b2","        return q, (x, h)","","    def predict(self, x: np.ndarray) -> np.ndarray:","        \"\"\"Q-values only. Accepts one state (11,) or a batch (n, 11).\"\"\"","        return self.forward(x)[0]","","    # ---------------------------------------------------------------- backward","","    def backward(self, cache, dq: np.ndarray) -> dict[str, np.ndarray]:","        \"\"\"Backpropagation: from dL/dq to the gradient of every weight.","","        Each line is the chain rule applied to one line of ``forward``, read","        from the bottom up.","        \"\"\"","        x, h = cache","        # q = h @ W2 + b2","        dW2 = h.T @ dq","        db2 = dq.sum(axis=0)","        dh = dq @ self.W2.T","        # h = max(0, z1): the gradient passes only where the unit was on","        dz1 = dh * (h > 0)","        # z1 = x @ W1 + b1","        dW1 = x.T @ dz1","        db1 = dz1.sum(axis=0)","        return {\"W1\": dW1, \"b1\": db1, \"W2\": dW2, \"b2\": db2}","","    # ---------------------------------------------------------------- copying","","    def copy(self) -> \"QNetwork\":","        n_in, n_hidden, n_out = self.sizes","        other = QNetwork(n_in, n_hidden, n_out)","        other.load_state(self.params)","        return other","","    def load_state(self, params: dict[str, np.ndarray]) -> None:","        \"\"\"Overwrite this network's weights with copies of ``params``.\"\"\"","        for name in PARAM_NAMES:","            getattr(self, name)[...] = params[name]","","    # ---------------------------------------------------------------- saving","","    def save(self, path, **metadata) -> None:","        \"\"\"Save the weights to a ``.npz`` file, with optional JSON metadata.\"\"\"","        np.savez(path, **self.params, metadata=json.dumps(metadata))","","    @classmethod","    def load(cls, path) -> \"QNetwork\":","        data = np.load(path)","        n_in, n_hidden = data[\"W1\"].shape","        n_out = data[\"W2\"].shape[1]","        net = cls(n_in, n_hidden, n_out)","        net.load_state({name: data[name] for name in PARAM_NAMES})","        return net","","    @staticmethod","    def load_metadata(path) -> dict:","        data = np.load(path)","        return json.loads(str(data[\"metadata\"])) if \"metadata\" in data else {}","","","def q_loss(q: np.ndarray, actions: np.ndarray, targets: np.ndarray):","    \"\"\"Mean squared error between Q(s, a) and the target y, for the action taken.","","    We only know what happened after the move we actually made, so only that","    output gets an error. The other two outputs get a gradient of zero.","","        L = mean((Q(s, a) - y)^2)      dL/dQ(s, a) = 2 (Q(s, a) - y) / n","","    Returns ``(loss, dq)`` where ``dq`` has the same shape as ``q``.","    \"\"\"","    n = len(actions)","    rows = np.arange(n)","    error = q[rows, actions] - targets","    loss = float(np.mean(error ** 2))","    dq = np.zeros_like(q)","    dq[rows, actions] = 2.0 * error / n","    return loss, dq","","","class Adam:","    \"\"\"The Adam optimiser, written out.","","    Plain gradient descent moves every weight by ``lr * grad``. Adam keeps two","    running averages per weight: ``m``, the average gradient (momentum), and","    ``v``, the average squared gradient (how noisy that weight is). The step is","    ``lr * m / sqrt(v)``, so each weight gets its own step size. Both averages","    start at zero, which biases them low for the first few steps; dividing by","    ``1 - beta^t`` corrects that.","    \"\"\"","","    def __init__(self, params: dict[str, np.ndarray], lr: float = 1e-3,","                 beta1: float = 0.9, beta2: float = 0.999, eps: float = 1e-8):","        self.lr = lr","        self.beta1 = beta1","        self.beta2 = beta2","        self.eps = eps","        self.t = 0","        self.m = {k: np.zeros_like(p) for k, p in params.items()}","        self.v = {k: np.zeros_like(p) for k, p in params.items()}","","    def step(self, params: dict[str, np.ndarray], grads: dict[str, np.ndarray]) -> None:","        \"\"\"Update ``params`` in place.\"\"\"","        self.t += 1","        c1 = 1.0 - self.beta1 ** self.t","        c2 = 1.0 - self.beta2 ** self.t","        for k, p in params.items():","            g = grads[k]","            self.m[k] = self.beta1 * self.m[k] + (1.0 - self.beta1) * g","            self.v[k] = self.beta2 * self.v[k] + (1.0 - self.beta2) * g * g","            m_hat = self.m[k] / c1","            v_hat = self.v[k] / c2","            p -= self.lr * m_hat / (np.sqrt(v_hat) + self.eps)","","","class SGD:","    \"\"\"Plain gradient descent, kept for comparison: ``w -= lr * grad``.\"\"\"","","    def __init__(self, params: dict[str, np.ndarray], lr: float = 1e-2):","        self.lr = lr","","    def step(self, params: dict[str, np.ndarray], grads: dict[str, np.ndarray]) -> None:","        for k, p in params.items():","            p -= self.lr * grads[k]"],"blocks":[{"start":1,"end":14,"note":"<p>The two lines of maths in the docstring are the whole network. The outputs have no activation because Q-values can be any real number.</p>"},{"start":15,"end":23,"note":"<p>Only NumPy, plus <code>json</code> for the metadata stored next to the weights.</p>"},{"start":24,"end":38,"note":"<p><b>Initialisation.</b> He initialisation for the ReLU layer, standard deviation <code>sqrt(2 / fan_in)</code>, keeps activations about the same size through the layer; the 2 makes up for ReLU zeroing half its inputs. The linear output layer uses <code>sqrt(1 / fan_in)</code>. Biases start at 0; the random weights already make the units different.</p>"},{"start":39,"end":51,"note":"<p>Shapes and parameter count. For 11, 64, 3 that is 704 + 64 + 192 + 3 = <b>963</b>. <code>params</code> returns the arrays themselves, not copies, so the optimiser can update them in place.</p>"},{"start":52,"end":62,"note":"<p><code>x @ W1 + b1</code> computes all 64 weighted sums for every row of the batch at once; the bias broadcasts over rows. <code>np.maximum(0, z1)</code> is ReLU. The cache keeps <code>x</code> and <code>h</code>, exactly what <code>backward</code> needs.</p>"},{"start":63,"end":68,"note":"<p>Q-values only. Works for one state of shape (11,) or a batch of shape (n, 11), because <code>@</code> and broadcasting treat both the same way.</p>"},{"start":69,"end":88,"note":"<p>Backprop: each line is the chain rule for one line of <code>forward</code>, read bottom up.</p><p><code>dW2 = h.T @ dq</code>: a weight's gradient is what came in times the error that came out, summed over the batch. <code>dh = dq @ W2.T</code>: the error flows back through the same weights, transposed. <code>dz1 = dh * (h &gt; 0)</code>: ReLU passes the gradient only where the unit was on. <code>dW1 = x.T @ dz1</code>: same pattern as the second layer.</p><p>Every gradient has the shape of the thing it is the gradient of. <code>tests/test_network.py</code> checks all of them against finite differences.</p>"},{"start":89,"end":101,"note":"<p><code>copy()</code> makes an independent network; <code>load_state</code> copies values <b>into</b> the existing arrays with <code>[...] =</code>. The target network depends on this being a copy: if it shared arrays with the online network, it would change on every update and stop doing its job.</p>"},{"start":102,"end":120,"note":"<p>Weights in a <code>.npz</code> (a zip of NumPy arrays) plus the training config as a JSON string. <code>load</code> reads the layer sizes from the arrays, so any saved size loads without extra arguments.</p>"},{"start":121,"end":139,"note":"<p>Mean squared error <b>only on the action taken</b>. The other outputs get a zero gradient, because this transition tells us nothing about them. The <code>2 / n</code> is the derivative of the mean of squares; forgetting the 2 silently halves every gradient.</p>"},{"start":140,"end":174,"note":"<p>Adam keeps a running mean of the gradient (<code>m</code>, momentum) and of its square (<code>v</code>, its scale) for every weight, and steps by <code>lr * m / sqrt(v)</code>, so every weight moves at roughly the learning rate whatever the size of its raw gradient. Dividing by <code>1 - beta^t</code> removes the bias from starting both averages at 0; on step 1 it makes the update exactly <code>lr * sign(g)</code>.</p>"},{"start":175,"end":183,"note":"<p>Plain gradient descent, kept for the ablation study. On this small problem it scored as well as Adam.</p>"}]},{"path":"snake_ai/agent.py","title":"The DQN agent: epsilon-greedy, replay memory, target network","group":"The library","order":3,"lines":["\"\"\"The learner: a Deep Q-Network (DQN) agent.","","Three ideas, each a few lines:","","1. Epsilon-greedy: with probability epsilon pick a random move (explore),","   otherwise the move with the highest Q-value (exploit).","2. Replay memory: store every step as (state, action, reward, next_state,","   terminal) and train on random batches of old steps, not just the last one.","3. Target network: a frozen copy of the network that computes the targets","   y = r + gamma * max Q_target(s', a'). It is refreshed every few hundred","   updates, so the thing we chase does not move every time we take a step.","\"\"\"","","from __future__ import annotations","","from dataclasses import asdict, dataclass","","import numpy as np","","from .game import N_ACTIONS, STATE_SIZE","from .network import SGD, Adam, QNetwork, q_loss","","","@dataclass","class Config:","    \"\"\"Every knob of a training run. The defaults are the ones used for the main model.\"\"\"","","    hidden: int = 64             # units in the hidden layer","    lr: float = 1e-3             # learning rate","    optimizer: str = \"adam\"      # \"adam\" or \"sgd\"","    gamma: float = 0.9           # discount: how much the future counts","    batch_size: int = 64         # transitions per update","    memory: int = 100_000        # replay memory capacity","    learn_start: int = 1_000     # steps collected before the first update","    target_sync: int = 500       # updates between target-network refreshes; 0 = no target network","    eps_start: float = 1.0       # epsilon in game 1","    eps_end: float = 0.01        # epsilon floor","    eps_decay_games: int = 150   # games to go from eps_start to eps_end","    board: int = 20              # board is board x board cells","","    def to_dict(self) -> dict:","        return asdict(self)","","","def epsilon_for_game(game: int, cfg: Config) -> float:","    \"\"\"Linear decay from eps_start to eps_end over eps_decay_games, then flat.\"\"\"","    if cfg.eps_decay_games <= 0:","        return cfg.eps_end","    frac = min(1.0, game / cfg.eps_decay_games)","    return cfg.eps_start + frac * (cfg.eps_end - cfg.eps_start)","","","class ReplayMemory:","    \"\"\"A fixed-size ring buffer of transitions, stored as NumPy arrays.","","    When it is full, the oldest transition is overwritten. ``sample`` draws a","    random batch, which breaks up the strong correlation between consecutive","    steps of the same game.","    \"\"\"","","    def __init__(self, capacity: int, state_size: int = STATE_SIZE, seed: int | None = None):","        self.capacity = capacity","        self.states = np.zeros((capacity, state_size))","        self.actions = np.zeros(capacity, dtype=np.int64)","        self.rewards = np.zeros(capacity)","        self.next_states = np.zeros((capacity, state_size))","        self.terminals = np.zeros(capacity)","        self.pos = 0     # where the next transition goes","        self.size = 0    # how many slots are filled","        self.rng = np.random.default_rng(seed)","","    def __len__(self) -> int:","        return self.size","","    def push(self, state, action, reward, next_state, terminal) -> None:","        i = self.pos","        self.states[i] = state","        self.actions[i] = action","        self.rewards[i] = reward","        self.next_states[i] = next_state","        self.terminals[i] = float(terminal)","        self.pos = (self.pos + 1) % self.capacity","        self.size = min(self.size + 1, self.capacity)","","    def sample(self, batch_size: int):","        idx = self.rng.integers(0, self.size, size=batch_size)","        return (self.states[idx], self.actions[idx], self.rewards[idx],","                self.next_states[idx], self.terminals[idx])","","","class Agent:","    def __init__(self, cfg: Config | None = None, seed: int | None = None):","        self.cfg = cfg or Config()","        self.rng = np.random.default_rng(seed)","        self.net = QNetwork(STATE_SIZE, self.cfg.hidden, N_ACTIONS, seed=seed)","        # With target_sync = 0 the \"target\" is the online network itself.","        self.target = self.net.copy() if self.cfg.target_sync > 0 else self.net","        if self.cfg.optimizer == \"adam\":","            self.opt = Adam(self.net.params, lr=self.cfg.lr)","        elif self.cfg.optimizer == \"sgd\":","            self.opt = SGD(self.net.params, lr=self.cfg.lr)","        else:","            raise ValueError(f\"unknown optimizer {self.cfg.optimizer!r}\")","        self.memory = ReplayMemory(self.cfg.memory, seed=None if seed is None else seed + 1)","        self.updates = 0","","    def act(self, state: np.ndarray, epsilon: float = 0.0) -> int:","        \"\"\"Epsilon-greedy: a random move with probability epsilon, else argmax Q.\"\"\"","        if self.rng.random() < epsilon:","            return int(self.rng.integers(N_ACTIONS))","        return int(np.argmax(self.net.predict(state)))","","    def remember(self, state, action, reward, next_state, terminal) -> None:","        self.memory.push(state, action, reward, next_state, terminal)","","    def learn(self) -> float | None:","        \"\"\"One gradient step on a random batch from memory. Returns the loss.\"\"\"","        cfg = self.cfg","        if len(self.memory) < max(cfg.batch_size, cfg.learn_start):","            return None","","        s, a, r, s2, terminal = self.memory.sample(cfg.batch_size)","","        # The target: the reward we got plus the discounted value of the best","        # move from where we landed. If the game ended there, the future is 0.","        q_next = self.target.predict(s2).max(axis=1)","        y = r + cfg.gamma * q_next * (1.0 - terminal)","","        q, cache = self.net.forward(s)","        loss, dq = q_loss(q, a, y)","        grads = self.net.backward(cache, dq)","        self.opt.step(self.net.params, grads)","","        self.updates += 1","        if cfg.target_sync > 0 and self.updates % cfg.target_sync == 0:","            self.target.load_state(self.net.params)","        return loss"],"blocks":[{"start":1,"end":13,"note":"<p>The three ideas that make up DQN, each a few lines below.</p>"},{"start":14,"end":23,"note":"<p>The agent knows the game only through <code>N_ACTIONS</code> and <code>STATE_SIZE</code>.</p>"},{"start":24,"end":44,"note":"<p>Every knob of a run in one place. <code>train.py</code> turns each field into a command-line flag automatically, and the config is saved with every model, so a result can always be traced back to its settings. <code>target_sync = 0</code> switches the target network off for the ablation study.</p>"},{"start":45,"end":52,"note":"<p>Linear decay per <b>game</b>, not per step, so a long game late in training does not burn through the schedule faster than a short early one.</p>"},{"start":53,"end":74,"note":"<p>A ring buffer: five arrays allocated once at full size, a write position and a fill count. When full, <code>pos</code> wraps to 0 and overwrites the oldest transition. Nothing is ever appended or shifted.</p>"},{"start":75,"end":84,"note":"<p>Write at <code>pos</code>, advance with <code>% capacity</code>, grow <code>size</code> until it reaches capacity.</p>"},{"start":85,"end":90,"note":"<p>A uniformly random batch, with replacement, by fancy indexing. Random batches break the correlation between consecutive steps.</p>"},{"start":91,"end":106,"note":"<p>The online network, its target copy (or the same object when <code>target_sync</code> is 0), the optimiser and the memory. The memory gets its own seed derived from the agent's, so sampling is reproducible too.</p>"},{"start":107,"end":112,"note":"<p>Epsilon-greedy: a random move with probability epsilon, otherwise the argmax of the Q-values.</p>"},{"start":113,"end":115,"note":"<p>Stores a transition. The flag stored is <code>terminal</code>, not <code>done</code>: a time-out ends the game but is not terminal.</p>"},{"start":116,"end":137,"note":"<p>One DQN update. Wait until the memory holds <code>learn_start</code> transitions, so early batches are not dominated by the first few steps.</p><p>The target is the Bellman equation: <code>y = r + gamma * max Q_target(s', a')</code>, with the future multiplied by <code>1 - terminal</code> so a crash is worth exactly its reward. Then a normal supervised step: forward, <code>q_loss</code>, backward, Adam. Every <code>target_sync</code> updates the target network gets a copy of the current weights.</p>"}]},{"path":"snake_ai/training.py","title":"The training loop and evaluation","group":"The library","order":4,"lines":["\"\"\"The training loop and the evaluation loop.","","Training plays games one after another. Every step: look at the state, pick a","move, play it, store what happened, and take one gradient step on a random","batch from memory. That is the whole algorithm.","\"\"\"","","from __future__ import annotations","","import csv","import time","from pathlib import Path","","import numpy as np","","from .agent import Agent, Config, epsilon_for_game","from .game import SnakeGame","from .network import QNetwork","","LOG_FIELDS = [\"game\", \"score\", \"steps\", \"epsilon\", \"loss\", \"reason\", \"record\", \"seconds\"]","","","def train(cfg: Config, games: int, seed: int = 0, log_path=None, model_path=None,","          verbose: bool = True, print_every: int = 25):","    \"\"\"Train a fresh agent for ``games`` games. Returns ``(agent, history)``.","","    ``history`` is a list of dicts, one per game, with the fields in LOG_FIELDS.","    If ``log_path`` is given the same rows are written there as CSV. If","    ``model_path`` is given, the weights are saved there at the end.","    \"\"\"","    agent = Agent(cfg, seed=seed)","    game = SnakeGame(cfg.board, cfg.board, seed=seed)","    history = []","    record = 0","    t0 = time.perf_counter()","","    log_file = None","    writer = None","    if log_path is not None:","        Path(log_path).parent.mkdir(parents=True, exist_ok=True)","        log_file = open(log_path, \"w\", newline=\"\")","        writer = csv.DictWriter(log_file, fieldnames=LOG_FIELDS)","        writer.writeheader()","","    try:","        for g in range(games):","            eps = epsilon_for_game(g, cfg)","            state = game.reset()","            losses = []","            done = False","            info = {}","            while not done:","                action = agent.act(state, eps)","                next_state, reward, done, info = game.step(action)","                agent.remember(state, action, reward, next_state, info[\"terminal\"])","                loss = agent.learn()","                if loss is not None:","                    losses.append(loss)","                state = next_state","","            record = max(record, game.score)","            row = {","                \"game\": g + 1,","                \"score\": game.score,","                \"steps\": game.steps,","                \"epsilon\": round(eps, 4),","                \"loss\": round(float(np.mean(losses)), 5) if losses else \"\",","                \"reason\": info.get(\"reason\", \"\"),","                \"record\": record,","                \"seconds\": round(time.perf_counter() - t0, 2),","            }","            history.append(row)","            if writer is not None:","                writer.writerow(row)","            if verbose and ((g + 1) % print_every == 0 or g == 0):","                recent = [h[\"score\"] for h in history[-print_every:]]","                print(f\"game {g + 1:5d}  score {game.score:3d}  \"","                      f\"mean(last {len(recent)}) {np.mean(recent):6.2f}  record {record:3d}  \"","                      f\"eps {eps:.3f}  {row['seconds']:7.1f}s\", flush=True)","    finally:","        if log_file is not None:","            log_file.close()","","    if model_path is not None:","        Path(model_path).parent.mkdir(parents=True, exist_ok=True)","        agent.net.save(model_path, config=cfg.to_dict(), games=games, seed=seed, record=record)","    return agent, history","","","def greedy_policy(net: QNetwork):","    \"\"\"Turn a network into a policy: state in, the move with the highest Q-value out.\"\"\"","    return lambda state: int(np.argmax(net.predict(state)))","","","def play_greedy(policy, game: SnakeGame):","    \"\"\"Play one game with no exploration. Yields the game after every step.","","    ``policy`` is a QNetwork or any function from a state to an action.","    \"\"\"","    if isinstance(policy, QNetwork):","        policy = greedy_policy(policy)","    state = game.reset()","    yield game","    while not game.done:","        state, _, _, _ = game.step(policy(state))","        yield game","","","def evaluate(policy, games: int = 100, board: int = 20, seed: int = 12345):","    \"\"\"Play ``games`` games with no exploration. Returns a dict of statistics.","","    ``policy`` is a QNetwork or any function from a state to an action, so the","    same code measures the network and the baselines.","    \"\"\"","    game = SnakeGame(board, board, seed=seed)","    scores, steps, reasons = [], [], {}","    for _ in range(games):","        for _ in play_greedy(policy, game):","            pass","        scores.append(game.score)","        steps.append(game.steps)","        reasons[game.end_reason] = reasons.get(game.end_reason, 0) + 1","    scores = np.array(scores)","    return {","        \"games\": games,","        \"mean\": float(scores.mean()),","        \"median\": float(np.median(scores)),","        \"std\": float(scores.std()),","        \"min\": int(scores.min()),","        \"max\": int(scores.max()),","        \"mean_steps\": float(np.mean(steps)),","        \"end_reasons\": reasons,","        \"scores\": scores.tolist(),","    }"],"blocks":[{"start":1,"end":7,"note":"<p>Act, step, remember, learn: one gradient step per game step.</p>"},{"start":8,"end":22,"note":"<p><code>LOG_FIELDS</code> is the column order of <code>log.csv</code>.</p>"},{"start":23,"end":45,"note":"<p>A fresh agent and game, both seeded with the same seed. The CSV log is opened up front and closed in a <code>finally</code>, so a run interrupted with Ctrl+C still leaves a readable log.</p>"},{"start":46,"end":60,"note":"<p>The whole algorithm. Note what goes into memory: <code>info[\"terminal\"]</code>, so time-outs are not treated as deaths.</p>"},{"start":61,"end":83,"note":"<p>One row per game: score, length in steps, epsilon, the mean loss of that game's updates, how it ended, the record so far and elapsed seconds.</p>"},{"start":84,"end":89,"note":"<p>The weights are saved with the config, seed and record as metadata.</p>"},{"start":90,"end":94,"note":"<p>Turns a network into a policy function. <code>evaluate</code> and <code>play_greedy</code> accept either a network or any state-to-action function, which is how the baselines are measured with exactly the same code.</p>"},{"start":95,"end":108,"note":"<p>A generator: it yields the game after every step, so the caller can draw it, count states, or just run it to the end.</p>"},{"start":109,"end":134,"note":"<p>100 games with no exploration, on boards from a fixed seed, so different models and baselines see the same food positions. Returns summary statistics, how games ended, and every score.</p>"}]},{"path":"snake_ai/baselines.py","title":"Baselines: random moves and a hand-written rule","group":"The library","order":5,"lines":["\"\"\"Two policies that are not learned, to measure the network against.","","A score only means something next to a baseline. ``random_policy`` is the","floor. ``rule_policy`` is the rule a person would write after looking at the","same 11 inputs: never move into danger, and prefer a move that heads towards","the food. If the network cannot beat or match that rule, it has not learned","much.","\"\"\"","","from __future__ import annotations","","import numpy as np","","from .game import CLOCKWISE, DOWN, LEFT, RIGHT, STRAIGHT, TURN_LEFT, TURN_RIGHT, UP, turn","","# index of each direction's one-hot input, and of each food input","_DIR_INPUT = {RIGHT: 3, DOWN: 4, LEFT: 5, UP: 6}","_TOWARDS_FOOD_INPUT = {LEFT: 7, RIGHT: 8, UP: 9, DOWN: 10}","_DANGER_INPUT = {STRAIGHT: 0, TURN_RIGHT: 1, TURN_LEFT: 2}","","","def random_policy(seed: int = 0):","    rng = np.random.default_rng(seed)","    return lambda state: int(rng.integers(3))","","","def heading(state) -> tuple[int, int]:","    \"\"\"Read the absolute direction back out of the one-hot inputs 3..6.\"\"\"","    for d in CLOCKWISE:","        if state[_DIR_INPUT[d]] > 0:","            return d","    raise ValueError(\"state has no direction set\")","","","def rule_policy(state) -> int:","    \"\"\"Safe and towards the food, else safe, else straight (it is doomed anyway).\"\"\"","    d = heading(state)","    safe = [a for a in (STRAIGHT, TURN_RIGHT, TURN_LEFT) if state[_DANGER_INPUT[a]] == 0]","    towards = [a for a in safe if state[_TOWARDS_FOOD_INPUT[turn(d, a)]] > 0]","    if towards:","        return towards[0]","    if safe:","        return safe[0]","    return STRAIGHT"],"blocks":[{"start":1,"end":9,"note":"<p>A score means little without something to compare it to. The random policy is the floor; the rule is what a person would write from the same 11 inputs.</p>"},{"start":10,"end":21,"note":"<p>Lookup tables from directions and actions to input positions, so the rule reads the state vector exactly as the network receives it.</p>"},{"start":22,"end":26,"note":"<p>Seeded, so the baseline is reproducible.</p>"},{"start":27,"end":34,"note":"<p>Recovers the absolute direction from the one-hot inputs 3 to 6.</p>"},{"start":35,"end":44,"note":"<p>Among the moves whose danger input is 0, take the first one whose new direction points at the food; otherwise the first safe move; otherwise straight, since every move crashes anyway. It scores 27.45 on the evaluation boards; the network scores 26.43 and agrees with it on 93.6% of the moves it plays.</p>"}]},{"path":"train.py","title":"Command line: train a model","group":"Scripts","order":10,"lines":["\"\"\"Train the Snake agent from scratch.","","    python train.py                      # the main run: 400 games, saves models/snake_q.npz","    python train.py --games 100 --out runs/quick","    python train.py --gamma 0.5 --hidden 16 --out runs/small","","A run writes three files into --out: log.csv (one row per game), model.npz","(the weights) and summary.json (config plus a 100-game greedy evaluation).","\"\"\"","","from __future__ import annotations","","import argparse","import json","from dataclasses import fields","from pathlib import Path","","from snake_ai.agent import Config","from snake_ai.training import evaluate, train","","","def main() -> None:","    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)","    parser.add_argument(\"--games\", type=int, default=400, help=\"number of training games\")","    parser.add_argument(\"--seed\", type=int, default=0, help=\"random seed for the game and the network\")","    parser.add_argument(\"--out\", default=\"runs/main\", help=\"folder for log.csv, model.npz and summary.json\")","    parser.add_argument(\"--save-model\", default=None,","                        help=\"also copy the weights here (e.g. models/snake_q.npz)\")","    parser.add_argument(\"--eval-games\", type=int, default=100, help=\"greedy games for the final evaluation\")","    defaults = Config()","    for f in fields(Config):","        parser.add_argument(f\"--{f.name.replace('_', '-')}\", type=type(getattr(defaults, f.name)),","                            default=getattr(defaults, f.name), help=f\"(default {getattr(defaults, f.name)})\")","    args = parser.parse_args()","","    cfg = Config(**{f.name: getattr(args, f.name) for f in fields(Config)})","    out = Path(args.out)","    out.mkdir(parents=True, exist_ok=True)","","    print(f\"training for {args.games} games, seed {args.seed}\")","    print(\"config:\", json.dumps(cfg.to_dict()))","    agent, history = train(cfg, args.games, seed=args.seed,","                           log_path=out / \"log.csv\", model_path=out / \"model.npz\")","    if args.save_model:","        agent.net.save(args.save_model, config=cfg.to_dict(), games=args.games, seed=args.seed,","                       record=max(h[\"score\"] for h in history))","","    stats = evaluate(agent.net, games=args.eval_games, board=cfg.board)","    summary = {","        \"config\": cfg.to_dict(),","        \"games\": args.games,","        \"seed\": args.seed,","        \"train_seconds\": history[-1][\"seconds\"],","        \"train_record\": max(h[\"score\"] for h in history),","        \"eval\": {k: v for k, v in stats.items() if k != \"scores\"},","        \"eval_scores\": stats[\"scores\"],","    }","    (out / \"summary.json\").write_text(json.dumps(summary, indent=2))","    print(f\"\\ngreedy evaluation over {stats['games']} games: mean {stats['mean']:.2f}, \"","          f\"median {stats['median']:.1f}, max {stats['max']}, ends {stats['end_reasons']}\")","    print(f\"saved {out / 'model.npz'}\" + (f\" and {args.save_model}\" if args.save_model else \"\"))","","","if __name__ == \"__main__\":","    main()"],"blocks":[{"start":1,"end":10,"note":"<p>Usage examples. Each run writes its log, weights and summary into its own folder.</p>"},{"start":11,"end":21,"note":"<p>The script only parses arguments and writes files; the learning lives in the library.</p>"},{"start":22,"end":39,"note":"<p>Every field of <code>Config</code> becomes a flag automatically (<code>--hidden</code>, <code>--gamma</code>, <code>--target-sync</code>, ...), so adding a knob to the config is enough to expose it.</p>"},{"start":40,"end":65,"note":"<p>Train, optionally copy the weights to <code>--save-model</code>, then evaluate with 100 greedy games and write <code>summary.json</code> with the config, timing and evaluation.</p>"}]},{"path":"evaluate.py","title":"Command line: measure a model","group":"Scripts","order":11,"lines":["\"\"\"Measure a trained network: play N games with no exploration and report the scores.","","    python evaluate.py                         # models/snake_q.npz, 100 games","    python evaluate.py --model runs/main/model.npz --games 500","    python evaluate.py --random                # baseline: an untrained network","\"\"\"","","from __future__ import annotations","","import argparse","","import numpy as np","","from snake_ai.network import QNetwork","from snake_ai.training import evaluate","","","def main() -> None:","    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)","    parser.add_argument(\"--model\", default=\"models/snake_q.npz\")","    parser.add_argument(\"--random\", action=\"store_true\", help=\"evaluate an untrained network\")","    parser.add_argument(\"--games\", type=int, default=100)","    parser.add_argument(\"--board\", type=int, default=20)","    parser.add_argument(\"--seed\", type=int, default=12345)","    args = parser.parse_args()","","    net = QNetwork(seed=0) if args.random else QNetwork.load(args.model)","    stats = evaluate(net, games=args.games, board=args.board, seed=args.seed)","    scores = np.array(stats[\"scores\"])","    print(f\"model:   {'untrained network' if args.random else args.model}\")","    print(f\"games:   {stats['games']} on a {args.board}x{args.board} board, epsilon = 0\")","    print(f\"score:   mean {stats['mean']:.2f}  median {stats['median']:.1f}  \"","          f\"std {stats['std']:.2f}  min {stats['min']}  max {stats['max']}\")","    print(f\"steps:   mean {stats['mean_steps']:.0f} per game\")","    print(f\"ended:   {stats['end_reasons']}\")","    hist, edges = np.histogram(scores, bins=10)","    print(\"\\nscore histogram\")","    for count, lo, hi in zip(hist, edges[:-1], edges[1:]):","        print(f\"  {lo:5.1f} - {hi:5.1f}  {'#' * int(count)}\")","","","if __name__ == \"__main__\":","    main()"],"blocks":[{"start":1,"end":7,"note":"<p>Plays greedy games and prints statistics plus a text histogram. <code>--random</code> measures an untrained network for comparison.</p>"},{"start":8,"end":17,"note":"<p>All the work is in <code>snake_ai.training.evaluate</code>.</p>"},{"start":18,"end":43,"note":"<p>The median is printed with one decimal on purpose: an early version rounded 25.5 to \"26\", which I then repeated in a commit message.</p>"}]},{"path":"play.py","title":"Command line: watch it play, or save a GIF","group":"Scripts","order":12,"lines":["\"\"\"Watch a trained network play Snake in the terminal, or save a GIF.","","    python play.py                               # watch models/snake_q.npz play","    python play.py --model runs/main/model.npz --fps 30","    python play.py --random                      # an untrained network, for comparison","    python play.py --gif assets/demo.gif         # write a GIF instead of drawing in the terminal","","Every frame shows the 11 inputs the network saw and the 3 Q-values it produced.","\"\"\"","","from __future__ import annotations","","import argparse","import sys","import time","","import numpy as np","","from snake_ai.game import ACTION_NAMES, STATE_LABELS, SnakeGame","from snake_ai.network import QNetwork","","# ANSI colours for the terminal view","TEAL = \"\\033[38;5;43m\"","RED = \"\\033[38;5;203m\"","DIM = \"\\033[2m\"","BOLD = \"\\033[1m\"","RESET = \"\\033[0m\"","","","def terminal_frame(game: SnakeGame, state, q, game_no: int) -> str:","    head = game.snake[0]","    lines = []","    lines.append(f\"{BOLD}game {game_no}   score {game.score}   steps {game.steps}{RESET}\")","    lines.append(\"+\" + \"--\" * game.width + \"+\")","    for y in range(game.height):","        row = \"|\"","        for x in range(game.width):","            p = (x, y)","            if p == head:","                row += TEAL + \"\u2588\u2588\" + RESET","            elif p in game.body:","                row += TEAL + \"\u2593\u2593\" + RESET","            elif p == game.food:","                row += RED + \"\u25cf\u25cf\" + RESET","            else:","                row += \"  \"","        lines.append(row + \"|\")","    lines.append(\"+\" + \"--\" * game.width + \"+\")","    on = [STATE_LABELS[i] for i, v in enumerate(state) if v > 0]","    lines.append(f\"{DIM}inputs on:{RESET} \" + \", \".join(on))","    best = int(np.argmax(q))","    qs = \"   \".join((BOLD if i == best else DIM) + f\"{ACTION_NAMES[i]} {q[i]:+6.2f}\" + RESET","                    for i in range(3))","    lines.append(f\"{DIM}Q-values:{RESET}  {qs}\")","    return \"\\n\".join(lines)","","","def watch(net: QNetwork, games: int, fps: float, seed: int, board: int) -> None:","    game = SnakeGame(board, board, seed=seed)","    delay = 1.0 / fps","    sys.stdout.write(\"\\033[2J\")  # clear the screen once","    try:","        for g in range(1, games + 1):","            state = game.reset()","            while True:","                q = net.predict(state)","                sys.stdout.write(\"\\033[H\" + terminal_frame(game, state, q, g) + \"\\033[J\")","                sys.stdout.flush()","                if game.done:","                    break","                state, _, _, _ = game.step(int(np.argmax(q)))","                time.sleep(delay)","            print(f\"\\n\\ngame {g} over: score {game.score}, ended by {game.end_reason}\")","            time.sleep(1.0)","    except KeyboardInterrupt:","        print(RESET)","","","def save_gif(net: QNetwork, path: str, seed: int, board: int, max_frames: int, fps: float) -> None:","    \"\"\"Draw each step with Pillow and save an animated GIF.\"\"\"","    from PIL import Image, ImageDraw, ImageFont","","    cell = 18","    pad = 16","    panel = 250","    w = pad * 2 + board * cell + panel","    h = pad * 2 + board * cell + 30","    bg, grid, ink, muted = (250, 250, 250), (228, 228, 232), (17, 17, 19), (138, 138, 146)","    teal, teal_dark, red = (43, 196, 170), (20, 140, 120), (214, 69, 65)","    blue = (43, 76, 242)","    try:","        font = ImageFont.truetype(\"DejaVuSansMono.ttf\", 12)","        font_b = ImageFont.truetype(\"DejaVuSansMono-Bold.ttf\", 14)","    except OSError:","        font = font_b = ImageFont.load_default()","","    game = SnakeGame(board, board, seed=seed)","    state = game.reset()","    frames = []","    while len(frames) < max_frames:","        q = net.predict(state)","        img = Image.new(\"RGB\", (w, h), bg)","        d = ImageDraw.Draw(img)","        d.text((pad, 8), f\"score {game.score}\", fill=ink, font=font_b)","        ox, oy = pad, pad + 20","        d.rectangle([ox - 1, oy - 1, ox + board * cell, oy + board * cell], outline=grid)","        if game.food is not None:","            fx, fy = game.food","            d.ellipse([ox + fx * cell + 3, oy + fy * cell + 3, ox + fx * cell + cell - 3,","                       oy + fy * cell + cell - 3], fill=red)","        for i, (x, y) in enumerate(game.snake):","            d.rectangle([ox + x * cell + 1, oy + y * cell + 1, ox + x * cell + cell - 2,","                         oy + y * cell + cell - 2], fill=teal_dark if i == 0 else teal)","        # side panel: inputs and Q-values","        px = ox + board * cell + 20","        d.text((px, oy - 2), \"INPUTS\", fill=muted, font=font)","        for i, label in enumerate(STATE_LABELS):","            yy = oy + 16 + i * 17","            on = state[i] > 0","            d.ellipse([px, yy + 2, px + 10, yy + 12], outline=blue, fill=blue if on else bg)","            d.text((px + 16, yy), label, fill=ink if on else muted, font=font)","        qy = oy + 16 + 11 * 17 + 12","        d.text((px, qy), \"Q-VALUES\", fill=muted, font=font)","        best = int(np.argmax(q))","        lo, hi = min(q.min(), 0.0), max(q.max(), 1.0)","        for i in range(3):","            yy = qy + 16 + i * 18","            d.text((px, yy), f\"{ACTION_NAMES[i]:>8}\", fill=ink if i == best else muted, font=font)","            bar = int(110 * (q[i] - lo) / (hi - lo + 1e-9))","            d.rectangle([px + 70, yy + 3, px + 70 + max(bar, 1), yy + 11],","                        fill=blue if i == best else grid)","        frames.append(img)","        if game.done:","            for _ in range(int(fps)):  # hold the last frame for a second","                frames.append(img)","            break","        state, _, _, _ = game.step(best)","","    frames[0].save(path, save_all=True, append_images=frames[1:], duration=int(1000 / fps),","                   loop=0, optimize=True)","    print(f\"wrote {path}: {len(frames)} frames, final score {game.score}\")","","","def main() -> None:","    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)","    parser.add_argument(\"--model\", default=\"models/snake_q.npz\")","    parser.add_argument(\"--random\", action=\"store_true\", help=\"use an untrained network instead\")","    parser.add_argument(\"--games\", type=int, default=3)","    parser.add_argument(\"--fps\", type=float, default=15)","    parser.add_argument(\"--seed\", type=int, default=7)","    parser.add_argument(\"--board\", type=int, default=20)","    parser.add_argument(\"--gif\", default=None, help=\"write a GIF of one game to this path\")","    parser.add_argument(\"--max-frames\", type=int, default=1500)","    args = parser.parse_args()","","    net = QNetwork(seed=args.seed) if args.random else QNetwork.load(args.model)","    if args.gif:","        save_gif(net, args.gif, args.seed, args.board, args.max_frames, args.fps)","    else:","        watch(net, args.games, args.fps, args.seed, args.board)","","","if __name__ == \"__main__\":","    main()"],"blocks":[{"start":1,"end":10,"note":"<p>Two outputs from the same loop: an ANSI terminal view, or a GIF drawn with Pillow. Both show the 11 inputs and 3 Q-values next to the board on every frame.</p>"},{"start":11,"end":29,"note":"<p>ANSI escape codes colour the terminal view; no extra libraries are needed.</p>"},{"start":30,"end":57,"note":"<p>Builds one frame as a string. <code>\\033[H</code> in <code>watch</code> moves the cursor home so each frame overwrites the last instead of scrolling.</p>"},{"start":58,"end":78,"note":"<p>The viewing loop: predict, draw, step, sleep. Ctrl+C exits cleanly.</p>"},{"start":79,"end":143,"note":"<p>Draws each step with Pillow: the board on the left, the inputs and Q-value bars on the right. The last frame is held for a second so the crash is visible.</p>"},{"start":144,"end":164,"note":"<p><code>--random</code> swaps in an untrained network, which is a good way to see what learning changed.</p>"}]},{"path":"analyze.py","title":"Analysis: baselines and the 256-input table","group":"Scripts","order":13,"lines":["\"\"\"Look inside the trained agent and compare it with the baselines.","","    python analyze.py                       # writes results/analysis.json","","1. Baselines: random moves, the hand-written rule, and the network, on the","   same 100 boards.","2. The whole input space: the 11 inputs can only take 256 combinations","   (8 danger patterns x 4 headings x 8 food directions). We list every one,","   how often the trained snake actually meets it, what the network does there","   and what the rule does there.","\"\"\"","","from __future__ import annotations","","import argparse","import itertools","import json","from pathlib import Path","","import numpy as np","","from snake_ai.baselines import random_policy, rule_policy","from snake_ai.game import ACTION_NAMES, SnakeGame","from snake_ai.network import QNetwork","from snake_ai.training import evaluate, play_greedy","","FOOD_PATTERNS = [(l, r, u, d) for l, r, u, d in itertools.product((0, 1), repeat=4)","                 if not (l and r) and not (u and d) and (l or r or u or d)]","","","def all_states():","    \"\"\"Every combination of inputs the game can produce (256).\"\"\"","    states = []","    for danger in itertools.product((0, 1), repeat=3):","        for heading in range(4):","            onehot = [0, 0, 0, 0]","            onehot[heading] = 1","            for food in FOOD_PATTERNS:","                states.append((*danger, *onehot, *food))","    return states","","","def main() -> None:","    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)","    parser.add_argument(\"--model\", default=\"models/snake_q.npz\")","    parser.add_argument(\"--games\", type=int, default=100)","    parser.add_argument(\"--out\", default=\"results/analysis.json\")","    args = parser.parse_args()","","    net = QNetwork.load(args.model)","","    print(\"baselines on the same boards (epsilon = 0):\")","    baselines = {}","    for name, policy in [(\"random\", random_policy(0)), (\"rule\", rule_policy), (\"network\", net)]:","        s = evaluate(policy, games=args.games)","        baselines[name] = {k: s[k] for k in (\"mean\", \"median\", \"std\", \"max\", \"mean_steps\", \"end_reasons\")}","        baselines[name][\"scores\"] = s[\"scores\"]","        print(f\"  {name:8s} mean {s['mean']:6.2f}  median {s['median']:4.0f}  max {s['max']:3d}  \"","              f\"ends {s['end_reasons']}\")","","    # Count which inputs the trained snake actually sees.","    visits: dict[tuple, int] = {}","    game = SnakeGame(20, 20, seed=12345)","    for _ in range(args.games):","        for g in play_greedy(net, game):","            if not g.done:","                key = tuple(int(v) for v in g.get_state())","                visits[key] = visits.get(key, 0) + 1","    total_visits = sum(visits.values())","","    states = all_states()","    x = np.array(states, dtype=float)","    q = net.predict(x)","    table = []","    agree_weighted = 0","    agree_states = 0","    for i, s in enumerate(states):","        net_a = int(np.argmax(q[i]))","        rule_a = rule_policy(np.array(s, dtype=float))","        n = visits.get(s, 0)","        same = net_a == rule_a","        agree_states += same","        agree_weighted += same * n","        table.append({\"state\": list(s), \"q\": [round(float(v), 3) for v in q[i]],","                      \"network\": ACTION_NAMES[net_a], \"rule\": ACTION_NAMES[rule_a], \"visits\": n})","","    seen = sum(1 for s in states if visits.get(s, 0) > 0)","    unknown = [s for s in visits if s not in set(states)]","    assert not unknown, f\"the game produced inputs outside the 256: {unknown[:3]}\"","    print(f\"\\ninput space: {len(states)} combinations, {seen} seen in {args.games} greedy games \"","          f\"({total_visits} steps)\")","    print(f\"network and rule agree on {agree_states}/{len(states)} combinations, and on \"","          f\"{100 * agree_weighted / total_visits:.1f}% of the steps actually played\")","","    out = {","        \"model\": args.model,","        \"games\": args.games,","        \"baselines\": baselines,","        \"n_states\": len(states),","        \"states_seen\": seen,","        \"steps\": total_visits,","        \"agree_states\": agree_states,","        \"agree_steps_pct\": round(100 * agree_weighted / total_visits, 2),","        \"table\": table,","    }","    Path(args.out).parent.mkdir(parents=True, exist_ok=True)","    Path(args.out).write_text(json.dumps(out, indent=1))","    print(f\"wrote {args.out}\")","","","if __name__ == \"__main__\":","    main()"],"blocks":[{"start":1,"end":12,"note":"<p>Two analyses: baselines on the same boards, and the complete input space.</p>"},{"start":13,"end":30,"note":"<p><code>FOOD_PATTERNS</code> lists the 8 possible food inputs: left, right or neither, combined with up, down or neither, minus \"neither and neither\", since the food is never on the head.</p>"},{"start":31,"end":42,"note":"<p>8 danger patterns times 4 headings times 8 food patterns: the 256 inputs the game can produce. A test checks that random play never produces anything outside this list.</p>"},{"start":43,"end":60,"note":"<p>Baselines first, all on the same seeded boards.</p>"},{"start":61,"end":112,"note":"<p>Replay 100 greedy games and count each input pattern. Then run all 256 through the network in one batch and compare its choice with the rule's, both per pattern and weighted by how often each pattern is met. The assertion fails loudly if the game ever produced an input outside the 256.</p>"}]},{"path":"experiments.py","title":"The ablation study","group":"Scripts","order":14,"lines":["\"\"\"Run the ablation study: change one setting at a time, train several seeds of each.","","    python experiments.py                  # everything, in parallel on all cores","    python experiments.py --only gamma     # one group","    python experiments.py --seeds 3 --workers 4","","For every variant it trains --seeds independent runs and writes, under","results/experiments/:","","    <variant>.csv    per-game score averaged over seeds (plus min and max)","    summary.json     one entry per variant: last-100 training mean and greedy","                     evaluation mean, each as mean and std over seeds","\"\"\"","","from __future__ import annotations","","import argparse","import json","import os","import time","from concurrent.futures import ProcessPoolExecutor","from dataclasses import replace","from pathlib import Path","","import numpy as np","","from snake_ai.agent import Config","from snake_ai.training import evaluate, train","","BASE = Config()","NO_REPLAY = dict(memory=1, batch_size=1, learn_start=1)","","# group -> list of (variant name, label for charts, config changes, games)","EXPERIMENTS = {","    \"baseline\": [(\"baseline\", \"baseline\", {}, 400)],","    \"long\": [(\"long_2000\", \"2000 games\", {}, 2000)],","    \"stability\": [","        (\"baseline\", \"replay + target\", {}, 400),","        (\"no_target\", \"no target network\", dict(target_sync=0), 400),","        (\"no_replay\", \"no replay memory\", NO_REPLAY, 400),","        (\"no_replay_no_target\", \"neither\", dict(NO_REPLAY, target_sync=0), 400),","    ],","    \"gamma\": [","        (\"gamma_0\", \"gamma 0\", dict(gamma=0.0), 400),","        (\"gamma_0.5\", \"gamma 0.5\", dict(gamma=0.5), 400),","        (\"baseline\", \"gamma 0.9\", {}, 400),","        (\"gamma_0.99\", \"gamma 0.99\", dict(gamma=0.99), 400),","    ],","    \"hidden\": [","        (\"hidden_4\", \"4 hidden\", dict(hidden=4), 400),","        (\"hidden_16\", \"16 hidden\", dict(hidden=16), 400),","        (\"baseline\", \"64 hidden\", {}, 400),","        (\"hidden_256\", \"256 hidden\", dict(hidden=256), 400),","    ],","    \"lr\": [","        (\"lr_1e-4\", \"lr 0.0001\", dict(lr=1e-4), 400),","        (\"baseline\", \"lr 0.001\", {}, 400),","        (\"lr_1e-2\", \"lr 0.01\", dict(lr=1e-2), 400),","    ],","    \"optimizer\": [","        (\"baseline\", \"Adam, lr 0.001\", {}, 400),","        (\"sgd_1e-3\", \"SGD, lr 0.001\", dict(optimizer=\"sgd\", lr=1e-3), 400),","        (\"sgd_1e-2\", \"SGD, lr 0.01\", dict(optimizer=\"sgd\", lr=1e-2), 400),","    ],","    \"epsilon\": [","        (\"eps_none\", \"no decay (always 0.01)\", dict(eps_decay_games=0), 400),","        (\"eps_50\", \"decay over 50\", dict(eps_decay_games=50), 400),","        (\"baseline\", \"decay over 150\", {}, 400),","        (\"eps_300\", \"decay over 300\", dict(eps_decay_games=300), 400),","    ],","}","","","def run_one(job):","    name, changes, games, seed = job","    cfg = replace(BASE, **changes)","    t0 = time.perf_counter()","    agent, history = train(cfg, games, seed=seed, verbose=False)","    stats = evaluate(agent.net, games=100, board=cfg.board, seed=10_000 + seed)","    return {","        \"name\": name,","        \"seed\": seed,","        \"scores\": [h[\"score\"] for h in history],","        \"eval_mean\": stats[\"mean\"],","        \"eval_max\": stats[\"max\"],","        \"seconds\": time.perf_counter() - t0,","    }","","","def main() -> None:","    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)","    parser.add_argument(\"--seeds\", type=int, default=5)","    parser.add_argument(\"--workers\", type=int, default=max(1, (os.cpu_count() or 2) - 1))","    parser.add_argument(\"--only\", default=None, help=\"run one group: \" + \", \".join(EXPERIMENTS))","    parser.add_argument(\"--out\", default=\"results/experiments\")","    args = parser.parse_args()","","    groups = {args.only: EXPERIMENTS[args.only]} if args.only else EXPERIMENTS","    variants = {}","    for group in groups.values():","        for name, _label, changes, games in group:","            variants[name] = (changes, games)","","    jobs = [(name, changes, games, seed) for name, (changes, games) in variants.items()","            for seed in range(args.seeds)]","    # longest jobs first so the pool finishes evenly","    jobs.sort(key=lambda j: -j[2])","    print(f\"{len(variants)} variants x {args.seeds} seeds = {len(jobs)} runs on {args.workers} workers\")","","    t0 = time.perf_counter()","    results: dict[str, list] = {name: [] for name in variants}","    with ProcessPoolExecutor(max_workers=args.workers) as pool:","        for r in pool.map(run_one, jobs):","            results[r[\"name\"]].append(r)","            print(f\"  {r['name']:22s} seed {r['seed']}  last-100 mean \"","                  f\"{np.mean(r['scores'][-100:]):6.2f}  eval mean {r['eval_mean']:6.2f}  \"","                  f\"({r['seconds']:.0f}s)\", flush=True)","","    out = Path(args.out)","    out.mkdir(parents=True, exist_ok=True)","    summary_path = out / \"summary.json\"","    summary = json.loads(summary_path.read_text()) if summary_path.exists() else {\"variants\": {}}","    summary[\"groups\"] = {g: [[n, label] for n, label, _, _ in rows] for g, rows in EXPERIMENTS.items()}","","    for name, runs in results.items():","        runs.sort(key=lambda r: r[\"seed\"])","        scores = np.array([r[\"scores\"] for r in runs], dtype=float)  # (seeds, games)","        with open(out / f\"{name}.csv\", \"w\") as f:","            f.write(\"game,mean,min,max\\n\")","            for g in range(scores.shape[1]):","                col = scores[:, g]","                f.write(f\"{g + 1},{col.mean():.2f},{col.min():.0f},{col.max():.0f}\\n\")","        last100 = scores[:, -100:].mean(axis=1)","        evals = np.array([r[\"eval_mean\"] for r in runs])","        summary[\"variants\"][name] = {","            \"changes\": variants[name][0],","            \"games\": variants[name][1],","            \"seeds\": len(runs),","            \"last100_mean\": round(float(last100.mean()), 2),","            \"last100_std\": round(float(last100.std()), 2),","            \"eval_mean\": round(float(evals.mean()), 2),","            \"eval_std\": round(float(evals.std()), 2),","            \"eval_per_seed\": [round(float(e), 2) for e in evals],","            \"eval_best_game\": int(max(r[\"eval_max\"] for r in runs)),","            \"seconds_per_run\": round(float(np.mean([r[\"seconds\"] for r in runs])), 1),","        }","","    summary_path.write_text(json.dumps(summary, indent=2))","    print(f\"\\ndone in {time.perf_counter() - t0:.0f}s, wrote {out}/\")","    print(f\"\\n{'variant':24s}{'last-100 train':>18s}{'greedy eval':>16s}\")","    for name in variants:","        v = summary[\"variants\"][name]","        print(f\"{name:24s}{v['last100_mean']:10.2f} \u00b1 {v['last100_std']:<5.2f}\"","              f\"{v['eval_mean']:9.2f} \u00b1 {v['eval_std']:<5.2f}\")","","","if __name__ == \"__main__\":","    main()"],"blocks":[{"start":1,"end":14,"note":"<p>One setting changed at a time, several seeds each, in parallel.</p>"},{"start":15,"end":33,"note":"<p><code>ProcessPoolExecutor</code> runs training runs in separate processes, so they use separate CPU cores. Threads would not help: Python's GIL lets only one thread run Python code at a time.</p>"},{"start":34,"end":73,"note":"<p>Each group compares variants of one setting. \"No replay\" is a memory of 1 with batches of 1: every transition is used once, immediately. The baseline appears in several groups but is trained only once per seed.</p>"},{"start":74,"end":89,"note":"<p>One training run plus a 100-game evaluation on boards seeded per run. Returns plain data so it can cross the process boundary.</p>"},{"start":90,"end":118,"note":"<p>Longest jobs first, so the pool does not finish with one 2,000-game run on a single core.</p>"},{"start":119,"end":158,"note":"<p>Per variant: a CSV of the per-game score averaged over seeds, and a summary entry with the mean and standard deviation over seeds. The standard deviation is the important number: it says how big a difference must be before it means anything.</p>"}]},{"path":"make_charts.py","title":"The README charts","group":"Scripts","order":15,"lines":["\"\"\"Draw the README charts from the saved results.","","    python make_charts.py          # reads results/, writes assets/*.png","","The style follows the guide: paper background, one blue accent for the thing","that matters, grey for everything it is compared with, labels on the lines.","\"\"\"","","from __future__ import annotations","","import csv","import json","from pathlib import Path","","import matplotlib","","matplotlib.use(\"Agg\")","import matplotlib.pyplot as plt  # noqa: E402","import numpy as np  # noqa: E402","","PAPER = \"#fafafa\"","INK = \"#111113\"","INK2 = \"#3b3b40\"","MUTED = \"#8a8a92\"","FAINT = \"#b9b9c0\"","RULE = \"#e4e4e8\"","BLUE = \"#2b4cf2\"","BLUE_SOFT = \"#a9b7ff\"","","OUT = Path(\"assets\")","","plt.rcParams.update({","    \"figure.facecolor\": PAPER, \"axes.facecolor\": PAPER, \"savefig.facecolor\": PAPER,","    \"axes.edgecolor\": RULE, \"axes.labelcolor\": MUTED, \"xtick.color\": MUTED, \"ytick.color\": MUTED,","    \"axes.spines.top\": False, \"axes.spines.right\": False, \"axes.grid\": True,","    \"grid.color\": RULE, \"grid.linewidth\": 0.8, \"axes.axisbelow\": True,","    \"font.family\": \"DejaVu Sans\", \"font.size\": 10, \"axes.titlesize\": 12,","    \"axes.titleweight\": \"bold\", \"axes.titlecolor\": INK, \"axes.titlelocation\": \"left\",","    \"axes.titlepad\": 12, \"xtick.major.size\": 0, \"ytick.major.size\": 0,","})","","","def moving_average(x, n):","    x = np.asarray(x, dtype=float)","    out = np.empty_like(x)","    for i in range(len(x)):","        out[i] = x[max(0, i - n + 1): i + 1].mean()","    return out","","","def read_log(path):","    with open(path) as f:","        return list(csv.DictReader(f))","","","def training_curve():","    rows = read_log(\"results/main/log.csv\")","    games = np.array([int(r[\"game\"]) for r in rows])","    scores = np.array([int(r[\"score\"]) for r in rows])","    eps = np.array([float(r[\"epsilon\"]) for r in rows])","    avg = moving_average(scores, 20)","    best = int(scores.max())","    best_game = int(games[scores.argmax()])","","    fig, ax = plt.subplots(figsize=(9, 4.4), dpi=150)","    ax.vlines(games, 0, scores, color=BLUE_SOFT, linewidth=1.0, alpha=0.9)","    ax.plot(games, avg, color=BLUE, linewidth=2.2)","    ax.set_title(\"Score per game while training\", color=INK)","    ax.set_xlabel(\"game\")","    ax.set_ylabel(\"apples eaten\")","    ax.set_ylim(0, best * 1.12)","","    # where epsilon is high the snake mostly moves at random","    random_until = int(np.argmax(eps < 0.5)) + 1","    ax.axvspan(0, random_until, color=RULE, alpha=0.5, linewidth=0)","    ax.text(random_until / 2, best * 1.03, \"mostly random moves\\n(epsilon > 0.5)\", ha=\"center\",","            va=\"top\", color=MUTED, fontsize=9)","    ax.annotate(f\"best game: {best}\", xy=(best_game, best), xytext=(best_game + 25, best * 0.98),","                color=INK2, fontsize=9, arrowprops=dict(arrowstyle=\"-\", color=FAINT, lw=0.8))","    ax.text(games[-1] + 4, avg[-1], \"20-game\\naverage\", color=BLUE, fontsize=9, va=\"center\")","    ax.set_xlim(0, len(games) + 45)","    ax.set_xticks(range(0, len(games) + 1, 50))","    fig.tight_layout()","    fig.savefig(OUT / \"training_curve.png\")","    plt.close(fig)","","","def ablations():","    summary = json.loads(Path(\"results/experiments/summary.json\").read_text())","    v = summary[\"variants\"]","    groups = [","        (\"Replay memory and target network\", \"stability\"),","        (\"Discount factor gamma\", \"gamma\"),","        (\"Hidden layer size\", \"hidden\"),","        (\"Learning rate\", \"lr\"),","        (\"Optimiser\", \"optimizer\"),","        (\"Exploration schedule\", \"epsilon\"),","    ]","    fig, axes = plt.subplots(len(groups), 1, figsize=(9, 11.5), dpi=150, sharex=True,","                             gridspec_kw={\"height_ratios\": [len(summary[\"groups\"][g]) for _, g in groups]})","    for ax, (title, key) in zip(axes, groups):","        rows = summary[\"groups\"][key]","        labels = [label for _, label in rows]","        means = [v[name][\"eval_mean\"] for name, _ in rows]","        stds = [v[name][\"eval_std\"] for name, _ in rows]","        y = np.arange(len(rows))[::-1]","        for yi, name, m, s in zip(y, [n for n, _ in rows], means, stds):","            color = BLUE if name == \"baseline\" else MUTED","            ax.hlines(yi, m - s, m + s, color=color, linewidth=1.6)","            ax.plot(m, yi, \"o\", color=color, markersize=8, markeredgecolor=PAPER, markeredgewidth=2)","            ax.text(m + s + 0.8, yi, f\"{m:.1f}\", va=\"center\", color=INK2, fontsize=9)","        ax.set_yticks(y, labels, color=INK2)","        ax.set_title(title)","        ax.grid(axis=\"y\", visible=False)","        ax.set_ylim(-0.7, len(rows) - 0.3)","    axes[-1].set_xlabel(\"mean score over 100 greedy games  (dot = mean of 5 seeds, line = \u00b1 1 std)\")","    axes[-1].set_xlim(0, 40)","    fig.suptitle(\"What each setting changes  (blue = the default)\", x=0.02, ha=\"left\",","                 fontsize=13, fontweight=\"bold\", color=INK)","    fig.tight_layout()","    fig.savefig(OUT / \"ablations.png\")","    plt.close(fig)","","","def learning_speed():","    \"\"\"Average curves of the stability variants: does it change how fast it learns?\"\"\"","    names = [(\"baseline\", \"replay + target (default)\", BLUE, \"-\", 2.4),","             (\"no_target\", \"no target network\", MUTED, \":\", 1.8),","             (\"no_replay\", \"no replay memory\", MUTED, \"--\", 1.6),","             (\"gamma_0\", \"gamma = 0\", INK2, \"-\", 1.6)]","    fig, ax = plt.subplots(figsize=(9, 4.4), dpi=150)","    ends = []","    for name, label, color, style, width in names:","        m = moving_average(read_log_simple(f\"results/experiments/{name}.csv\"), 20)","        ax.plot(np.arange(1, len(m) + 1), m, color=color, linestyle=style, linewidth=width)","        ends.append([m[-1], label, color])","    # spread the end labels so they never overlap (at least 1.8 units apart)","    ends.sort(key=lambda e: e[0])","    for i in range(1, len(ends)):","        ends[i][0] = max(ends[i][0], ends[i - 1][0] + 1.8)","    for y, label, color in ends:","        ax.text(406, y, label, color=color, va=\"center\", fontsize=9)","    ax.set_xlim(0, 540)","    ax.set_xticks(range(0, 401, 50))","    ax.set_title(\"Learning curves, average of 5 seeds (20-game moving average)\")","    ax.set_xlabel(\"game\")","    ax.set_ylabel(\"apples eaten\")","    fig.tight_layout()","    fig.savefig(OUT / \"learning_speed.png\")","    plt.close(fig)","","","def read_log_simple(path):","    with open(path) as f:","        return [float(r[\"mean\"]) for r in csv.DictReader(f)]","","","def baselines():","    a = json.loads(Path(\"results/analysis.json\").read_text())[\"baselines\"]","    names = [(\"random\", \"random moves\"), (\"rule\", \"hand-written rule\"), (\"network\", \"trained network\")]","    fig, ax = plt.subplots(figsize=(9, 2.6), dpi=150)","    for i, (key, label) in enumerate(names):","        y = len(names) - 1 - i","        m = a[key][\"mean\"]","        ax.barh(y, m, height=0.5, color=BLUE if key == \"network\" else FAINT)","        ax.text(m + 0.5, y, f\"{m:.2f}\", va=\"center\", color=INK2, fontsize=9)","    ax.set_yticks(range(len(names)), [label for _, label in names][::-1], color=INK2)","    ax.grid(axis=\"y\", visible=False)","    ax.set_xlim(0, 32)","    ax.set_title(\"Mean score on the same 100 boards\")","    fig.tight_layout()","    fig.savefig(OUT / \"baselines.png\")","    plt.close(fig)","","","def main():","    OUT.mkdir(exist_ok=True)","    training_curve()","    ablations()","    learning_speed()","    baselines()","    print(\"wrote\", \", \".join(sorted(str(p) for p in OUT.glob(\"*.png\"))))","","","if __name__ == \"__main__\":","    main()"],"blocks":[{"start":1,"end":8,"note":"<p>Every chart is drawn from files in <code>results/</code>, never from numbers typed by hand.</p>"},{"start":9,"end":42,"note":"<p>The same colour tokens as the guide: paper, ink, one blue accent for the thing that matters, grey for comparisons.</p>"},{"start":43,"end":55,"note":"<p>A trailing average, so the first points average over fewer games instead of being dropped.</p>"},{"start":56,"end":87,"note":"<p>Score bars per game, a 20-game average in blue, and a band where epsilon is above 0.5.</p>"},{"start":88,"end":124,"note":"<p>One row per variant: the mean over 5 seeds as a dot, plus and minus one standard deviation as a line. The default is blue.</p>"},{"start":125,"end":157,"note":"<p>Learning curves for the replay and target-network variants. End labels are pushed apart so they never overlap, and line styles differ so the greys can be told apart.</p>"},{"start":158,"end":175,"note":"<p>Random, rule and network on the same boards.</p>"},{"start":176,"end":186,"note":"<p>Writes everything to <code>assets/</code>.</p>"}]},{"path":"tests/test_network.py","title":"Tests: the network and the gradient check","group":"Tests","order":20,"lines":["\"\"\"The network: shapes, a numerical gradient check, and the optimisers.\"\"\"","","import numpy as np","","from snake_ai.network import SGD, Adam, QNetwork, q_loss","","","def loss_of(net, x, a, y):","    q, _ = net.forward(x)","    return q_loss(q, a, y)[0]","","","def test_shapes():","    net = QNetwork(11, 64, 3, seed=0)","    assert net.W1.shape == (11, 64) and net.b1.shape == (64,)","    assert net.W2.shape == (64, 3) and net.b2.shape == (3,)","    assert net.n_params() == 11 * 64 + 64 + 64 * 3 + 3 == 963","    assert net.predict(np.zeros(11)).shape == (3,)","    assert net.predict(np.zeros((5, 11))).shape == (5, 3)","","","def test_forward_matches_formula():","    net = QNetwork(4, 5, 3, seed=1)","    x = np.array([[1.0, 0.0, 1.0, 0.0]])","    h = np.maximum(0, x @ net.W1 + net.b1)","    assert np.allclose(net.predict(x), h @ net.W2 + net.b2)","","","def test_q_loss_only_touches_taken_action():","    q = np.array([[1.0, 2.0, 3.0], [0.0, 0.0, 0.0]])","    a = np.array([2, 0])","    y = np.array([1.0, 1.0])","    loss, dq = q_loss(q, a, y)","    # errors: 3 - 1 = 2 and 0 - 1 = -1 -> mean of squares = (4 + 1) / 2","    assert np.isclose(loss, 2.5)","    assert np.allclose(dq, [[0, 0, 2 * 2 / 2], [2 * -1 / 2, 0, 0]])","","","def test_gradient_check():","    \"\"\"Compare backprop to finite differences on every single weight.","","    If backprop has a bug, the two disagree. Relative error around 1e-7 or","    smaller means they agree.","    \"\"\"","    rng = np.random.default_rng(0)","    net = QNetwork(11, 16, 3, seed=0)","    # biases start at 0, give them values so their gradients are tested properly","    net.b1[:] = rng.normal(0, 0.1, 16)","    net.b2[:] = rng.normal(0, 0.1, 3)","    x = rng.integers(0, 2, size=(8, 11)).astype(float)","    a = rng.integers(0, 3, size=8)","    y = rng.normal(0, 5, size=8)","","    q, cache = net.forward(x)","    _, dq = q_loss(q, a, y)","    grads = net.backward(cache, dq)","","    h = 1e-6","    for name, p in net.params.items():","        numeric = np.zeros_like(p)","        it = np.nditer(p, flags=[\"multi_index\"])","        for _ in it:","            i = it.multi_index","            old = p[i]","            p[i] = old + h","            plus = loss_of(net, x, a, y)","            p[i] = old - h","            minus = loss_of(net, x, a, y)","            p[i] = old","            numeric[i] = (plus - minus) / (2 * h)","        rel = np.linalg.norm(numeric - grads[name]) / (np.linalg.norm(numeric) + np.linalg.norm(grads[name]) + 1e-12)","        assert rel < 1e-6, f\"{name}: relative error {rel:.2e}\"","","","def test_adam_fits_a_tiny_regression():","    \"\"\"The network should be able to memorise a handful of targets.\"\"\"","    rng = np.random.default_rng(0)","    net = QNetwork(11, 32, 3, seed=0)","    opt = Adam(net.params, lr=1e-2)","    x = rng.integers(0, 2, size=(16, 11)).astype(float)","    a = rng.integers(0, 3, size=16)","    y = rng.normal(0, 3, size=16)","    first = loss_of(net, x, a, y)","    for _ in range(500):","        q, cache = net.forward(x)","        _, dq = q_loss(q, a, y)","        opt.step(net.params, net.backward(cache, dq))","    assert loss_of(net, x, a, y) < first * 0.01","","","def test_adam_first_step_is_lr_sized():","    \"\"\"After bias correction, Adam's first step is about lr * sign(grad).\"\"\"","    p = {\"w\": np.array([1.0, -2.0, 3.0])}","    opt = Adam(p, lr=0.1)","    opt.step(p, {\"w\": np.array([0.5, -100.0, 1e-3])})","    assert np.allclose(p[\"w\"], [0.9, -1.9, 2.9], atol=1e-4)","","","def test_sgd_step():","    p = {\"w\": np.array([1.0, 2.0])}","    SGD(p, lr=0.5).step(p, {\"w\": np.array([2.0, -2.0])})","    assert np.allclose(p[\"w\"], [0.0, 3.0])","","","def test_copy_is_independent():","    net = QNetwork(seed=0)","    other = net.copy()","    assert np.array_equal(net.W1, other.W1)","    other.W1 += 1","    assert not np.array_equal(net.W1, other.W1)","","","def test_save_and_load(tmp_path):","    net = QNetwork(11, 8, 3, seed=5)","    path = tmp_path / \"m.npz\"","    net.save(path, note=\"hello\", games=3)","    loaded = QNetwork.load(path)","    x = np.random.default_rng(0).random((4, 11))","    assert np.allclose(net.predict(x), loaded.predict(x))","    assert QNetwork.load_metadata(path) == {\"note\": \"hello\", \"games\": 3}"],"blocks":[{"start":1,"end":2,"note":"<p>The most important test file in the project.</p>"},{"start":3,"end":12,"note":"<p><code>loss_of</code> runs a forward pass and returns only the loss, which is all the numerical gradient needs.</p>"},{"start":13,"end":21,"note":"<p>Shapes and the exact parameter count, 963.</p>"},{"start":22,"end":28,"note":"<p>The forward pass against the formula written out by hand.</p>"},{"start":29,"end":38,"note":"<p>Checks both the loss value and that only the taken action gets a gradient, with numbers small enough to verify in your head.</p>"},{"start":39,"end":74,"note":"<p>For every single weight: nudge it by plus and minus 1e-6, measure the loss, and compare <code>(L+ - L-) / 2h</code> with what <code>backward</code> says. The biases are set to non-zero values first so their gradients are really tested. The relative error must be below 1e-6; it comes out around 1e-9.</p>"},{"start":75,"end":90,"note":"<p>An end-to-end check that forward, loss, backward and Adam together can drive the loss down: memorise 16 random targets.</p>"},{"start":91,"end":98,"note":"<p>With bias correction, Adam's first step is the learning rate times the sign of the gradient, whether the gradient is 0.5, -100 or 0.001.</p>"},{"start":99,"end":104,"note":"<p>Plain gradient descent, checked by hand.</p>"},{"start":105,"end":112,"note":"<p>The target network relies on this: changing the copy must not change the original.</p>"},{"start":113,"end":120,"note":"<p>A saved model loads with the same predictions and the same metadata.</p>"}]}]};
